(x, y, t) => {
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx=x+wx1, sy=y+wy1;
  const wx2=Math.sin(sx*0.03-t*0.15)*8+Math.cos(sy*0.025+t*0.1)*6;
  const wy2=Math.cos(sx*0.025+t*0.2)*8+Math.sin(sy*0.03-t*0.18)*6;
  const fx=sx+wx2, fy=sy+wy2;
  const cx=240, cy=120, dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy, fx-cx);
  const src=[
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75)*40,0.05,2.8]
  ];
  let aS=0,iS=0,a2=0,i2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp); iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    a2+=Math.sin(d*f*1.5-t*sp*0.8+0.5)*0.5; i2+=Math.cos(d*f*1.3+t*sp*0.4-0.8)*0.5;
  }
  const n=src.length, act=(aS+a2)/n, inh=(iS+i2)/n;
  const bg=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1)+Math.sin(fx*0.05+fy*0.035-t*0.6))/3
    +Math.sin((fx+fy)*0.12+t*2.5)*0.15+Math.sin((fx-fy)*0.1-t*2)*0.15
    +Math.sin(fx*0.08+t*1.8)*Math.cos(fy*0.06-t*1.3)*0.1;
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.25
    +Math.sin(dist*0.07-ang*2-t*2.0)*0.15+Math.sin(dist*0.03+ang*6-t*0.8)*0.1;
  const detail=Math.sin(fx*0.3+t)*Math.sin(fy*0.3-t)*0.1+Math.sin(fx*0.6+fy*0.4+t*2)*0.05;
  const raw=act-inh*0.7+bg*0.3+spiral+detail;
  const reaction=Math.tanh(raw*2.2);
  const reaction2=Math.tanh((reaction+Math.sin(fx*0.08-fy*0.06+t*0.5)*0.3-reaction*0.2)*2.5);
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5+Math.sin(fx*0.2-fy*0.15+t*0.7)*0.3)*1.5)*0.25;
  const vignette=1.0-dist/400*0.3;
  const blend=reaction2*0.65+cell*0.2+reaction*0.15, v=(blend*0.5+0.5)*vignette;
  const pal=[[4,10,38],[8,32,72],[12,68,105],[18,115,125],[45,160,130],[110,185,105],[175,195,75],[215,165,55],[205,105,50],[170,55,65],[120,35,85],[65,20,95],[30,12,55],[4,10,38]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(reaction2*Math.PI)*0.15+Math.abs(reaction)*0.1;
  const edge=Math.abs(reaction2)>0.65?1.2:Math.abs(reaction2)>0.4?1.05:1.0;
  const angS=Math.sin(ang*2+t*0.3)*0.05;
  return[
    Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f+angS*30)*lum*edge))|0,
    Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f+angS*15)*lum*edge))|0,
    Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f-angS*20)*lum*edge))|0
  ];
}
